class Solution:
    def sumOfBlocks(self, n: int) -> int:
        MOD = 10 ** 9 + 7
        ans, num = 0, 1
        for i in range(1, n + 1):
            cur = 1
            for _ in range(i):
                cur = cur * num % MOD
                num += 1
            ans = (ans + cur) % MOD
        return ans

