        long long ans = 0, num = 1;
        for (int i = 1; i <= n; i++) {
            long long cur = 1;
            for (int j = 0; j < i; j++) {
                cur = cur * (num % MOD) % MOD;
                num++;
            }
            ans = (ans + cur) % MOD;
