class Solution:
    def sumOfBlocks(self, n: int) -> int:
        MOD = 10 ** 9 + 7
        N = n * (n + 1) // 2
        fact = [1] * (N + 1)
        for i in range(1, N + 1):
            fact[i] = fact[i - 1] * i % MOD
        invf = [1] * (N + 1)
        invf[N] = pow(fact[N], MOD - 2, MOD)
        for i in range(N, 0, -1):
            invf[i - 1] = invf[i] * i % MOD
        ans = 0
        for i in range(1, n + 1):
            T = i * (i + 1) // 2
            ans = (ans + fact[T] * invf[T - i]) % MOD
        return ans

