class Solution {
public:
    int sumOfBlocks(int n) {
        const long long MOD = 1e9 + 7;
        long long N = (long long)n * (n + 1) / 2;
        vector<long long> f(N + 1, 1), inv(N + 1, 1);
        for (long long i = 1; i <= N; i++) f[i] = f[i-1] * i % MOD;
        inv[N] = 1;
        long long base = f[N], res = 1, e = MOD - 2;
        while (e) { if (e & 1) res = res * base % MOD; base = base * base % MOD; e >>= 1; }
        inv[N] = res;
        for (long long i = N; i >= 1; i--) inv[i-1] = inv[i] * i % MOD;
        long long ans = 0;
        for (int i = 1; i <= n; i++) {
            long long T = (long long)i * (i + 1) / 2;
            ans = (ans + f[T] * inv[T - i]) % MOD;
        }
        return (int)ans;
