class Solution {
    public int sumOfBlocks(int n) {
        final long MOD = 1000000007L;
        long N = (long) n * (n + 1) / 2;
        long[] f = new long[(int) N + 1], inv = new long[(int) N + 1];
        f[0] = 1;
        for (int i = 1; i <= (int) N; i++) f[i] = f[i-1] * i % MOD;
        inv[(int) N] = pow(f[(int) N], MOD - 2, MOD);
        for (int i = (int) N; i >= 1; i--) inv[i-1] = inv[i] * i % MOD;
        long ans = 0;
        for (int i = 1; i <= n; i++) {
            long T = (long) i * (i + 1) / 2;
            ans = (ans + f[(int) T] * inv[(int)(T - i)]) % MOD;
        }
        return (int) ans;
    }
    private long pow(long b, long e, long m) {
        long r = 1; b %= m;
        while (e > 0) { if ((e & 1) == 1) r = r * b % m; b = b * b % m; e >>= 1; }
        return r;
    }
}

