    const MOD = 1e9 + 7;
    const N = n * (n + 1) / 2;
    const f = new Array(N + 1).fill(1), inv = new Array(N + 1).fill(1);
    for (let i = 1; i <= N; i++) f[i] = f[i-1] * i % MOD;
    let res = 1, base = f[N], e = MOD - 2;
    while (e > 0) { if (e % 2 === 1) res = res * base % MOD; base = base * base % MOD; e = Math.floor(e / 2); }
    inv[N] = res;
    for (let i = N; i >= 1; i--) inv[i-1] = inv[i] * i % MOD;
    let ans = 0;
    for (let i = 1; i <= n; i++) {
        const T = i * (i + 1) / 2;
        ans = (ans + f[T] * inv[T - i]) % MOD;
    }
    return ans;
};
